void Solver::bump_var(int var, double coeff) {
    // Compute the increment based on the current decay factor and the provided coefficient
    double inc = var_inc * coeff;
    // Safely increase the activity, ensuring it stays non‑negative
    activity[var] = std::max(0.0, activity[var] + inc);

    // Rescale all activities if any entry grows beyond a safe threshold to avoid overflow
    const double RESCALE_THRESHOLD = 1e150;
    if (activity[var] > RESCALE_THRESHOLD) {
        double scale = 1e-150;                     // Scale factor to bring values back into range
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;                          // Keep the decay factor consistent with the rescaling
    }

    // If the variable is present in the VSIDS heap, update its position according to the new activity
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
